CREATE OR REPLACE FUNCTION public.plan_post_date(_post uuid,_when timestamptz,_platform public.platform_type DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.post_cards; BEGIN SELECT * INTO p FROM public.post_cards WHERE id=_post FOR UPDATE; IF NOT public.can_edit_content(auth.uid()) OR NOT public.is_workspace_member(auth.uid()) OR NOT public.user_can_access_client(auth.uid(),p.client_id) THEN RAISE EXCEPTION 'Your role cannot plan this post'; END IF; IF p.id IS NULL OR p.is_sample OR p.approval_status IN ('posted','archived') THEN RAISE EXCEPTION 'This post cannot be moved in the planner'; END IF; IF _when IS NULL OR _when<=now() THEN RAISE EXCEPTION 'Choose a future planning date'; END IF; IF p.delivery_status='scheduled' THEN IF _platform IS NOT NULL AND _platform<>p.platform THEN RAISE EXCEPTION 'Cancel delivery before changing platform'; END IF; PERFORM public.submit_delivery(p.id,p.target_account_ids,_when,coalesce(p.timezone,'UTC'),p.apply_ai_disclosure); ELSE UPDATE public.post_cards SET scheduled_for=_when,platform=coalesce(_platform,platform),updated_by=auth.uid() WHERE id=p.id; END IF; END $$;
REVOKE ALL ON FUNCTION public.plan_post_date(uuid,timestamptz,public.platform_type) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.plan_post_date(uuid,timestamptz,public.platform_type) TO authenticated;
DO $$ DECLARE d text; BEGIN
SELECT pg_get_functiondef('public.submit_delivery(uuid,uuid[],timestamptz,text,boolean)'::regprocedure) INTO d;
d:=replace(d,'-- Changing reviewable channels','IF EXISTS(SELECT 1 FROM public.delivery_operations WHERE post_card_id=p.id AND status IN (''sending'',''awaiting_confirmation'')) THEN RAISE EXCEPTION ''Reconcile pending delivery before changing or retrying it''; END IF;
-- Changing reviewable channels');
d:=replace(d,'SELECT * INTO w FROM public.workspace_settings WHERE id=true; intended:=','UPDATE public.delivery_operations SET status=''skipped'',reason=''Superseded pending schedule'',updated_at=now() WHERE post_card_id=p.id AND status=''scheduled'' AND (revision<>p.readiness_revision OR NOT social_account_id=ANY(ids) OR _when IS NULL);
SELECT * INTO w FROM public.workspace_settings WHERE id=true; intended:='); EXECUTE d;
SELECT pg_get_functiondef('public.process_scheduled_posts(integer)'::regprocedure) INTO d;
d:=replace(d,'BEGIN g:=public.delivery_readiness_internal','BEGIN IF NOT public.can_edit_content(p.scheduled_by) THEN RAISE EXCEPTION ''Scheduled by a user who no longer has publishing permission''; END IF; g:=public.delivery_readiness_internal');
d:=replace(d,'FOR o IN SELECT * FROM public.delivery_operations WHERE post_card_id=p.id AND revision=p.readiness_revision AND status=''scheduled''','FOR o IN SELECT * FROM public.delivery_operations WHERE post_card_id=p.id AND status=''scheduled''');
d:=replace(d,'WHEN NOT coalesce((g->>''canDeliver'')::boolean,false)','WHEN o.revision<>p.readiness_revision OR NOT coalesce((g->>''canDeliver'')::boolean,false)');
d:=replace(d,'FROM public.delivery_operations WHERE post_card_id=p.id AND revision=p.readiness_revision;','FROM public.delivery_operations WHERE post_card_id=p.id AND intended_at=p.scheduled_for;'); EXECUTE d;
SELECT pg_get_functiondef('public.mark_posted_manual(uuid,text)'::regprocedure) INTO d;
d:=replace(d,'PERFORM set_config(''app.delivery_authorized''','UPDATE public.delivery_operations SET status=''skipped'',reason=''Manually confirmed; pending delivery canceled'',updated_at=now() WHERE post_card_id=p.id AND status=''scheduled'';
PERFORM set_config(''app.delivery_authorized'''); EXECUTE d;
SELECT pg_get_functiondef('public.reconcile_delivery(uuid,text,text,text)'::regprocedure) INTO d;
d:=replace(d,'UPDATE public.post_cards SET delivery_status=','PERFORM set_config(''app.delivery_authorized'',''true'',true);
UPDATE public.post_cards SET confirmed_at=CASE WHEN _outcome=''platform_confirmed'' THEN now() ELSE confirmed_at END,confirmed_by=CASE WHEN _outcome=''platform_confirmed'' THEN o.created_by ELSE confirmed_by END,delivery_status='); EXECUTE d;
END $$;
CREATE OR REPLACE FUNCTION public.guard_confirmation_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND (NEW.is_sample OR NEW.confirmed_at IS NOT NULL OR NEW.confirmation_source IS NOT NULL OR (TG_TABLE_NAME='external_posts' AND to_jsonb(NEW)->>'is_commented'='true') OR (TG_TABLE_NAME='comments' AND to_jsonb(NEW)->>'approval_status'='posted')) THEN RAISE EXCEPTION 'New comments must start unconfirmed'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_external_confirmation_insert BEFORE INSERT ON public.external_posts FOR EACH ROW EXECUTE FUNCTION public.guard_confirmation_insert();
CREATE TRIGGER guard_comment_confirmation_insert BEFORE INSERT ON public.comments FOR EACH ROW EXECUTE FUNCTION public.guard_confirmation_insert();
